+#[serde(rename_all = "camelCase")]
+#[cfg_attr(feature = "export-ts", ts(export, export_to = "./gitea/token.ts"))]
+pub struct GiteaAccountIdentifier {
+ pub username: String,
+ pub host: String,
+}
