comment_B:
SafeSearch domain matching is overly broad: pattern "google." combined with `domain.contains(".$pattern")` will redirect *any* `*.google.*` host (e.g., `accounts.google.com`, `mail.google.com`) to `forcesafesearch.google.com`, breaking non-search Google services. Consider narrowing matching to known Google Search hostnames (e.g., `google.<tld>` / `www.google.<tld>` and any explicitly-allowed search subdomains) rather than any domain containing `.google.`.
```suggestion
 * "www.google.co.uk", etc., but not "accounts.google.com" or "mail.google.com".
 * Pattern "bing.com" matches "bing.com" and "www.bing.com".
 */
 private fun matchesDomain(domain: String, pattern: String): Boolean {
 if (pattern.endsWith(".")) {
 // Pattern like "google." is treated specially: it matches only search hostnames
 // where "google" is the left-most label, optionally prefixed by "www".
 // Examples that match:
 // - google.com, google.co.uk
 // - www.google.com, www.google.co.uk
 // Examples that do NOT match:
 // - accounts.google.com
 // - mail.google.com
 val baseLabel = pattern.removeSuffix(".") // e.g., "google"
 val parts = domain.split('.')
 if (parts.isEmpty()) {
 return false
 }
 val idx = parts.indexOf(baseLabel)
 if (idx == -1) {
 return false
 }
 // Allow "google.<tld>" or "www.google.<tld>", but not "accounts.google.com", etc.
 return idx == 0 || (idx == 1 && parts[0] == "www")
```

