 tempValues: any,
 parentsKey: React.Key[] | undefined,
 currentTransforms: any,
 rootMergeObjects: any[],
+ visited: Set<any>,
 ): any {
+ if (tempValues != null && typeof tempValues === 'object') {
+ if (visited.has(tempValues)) {
+ return tempValues;
+ }
+ visited.add(tempValues);
+ }

