+use dashmap::DashMap;
+use std::sync::OnceLock;
+use std::sync::atomic::{AtomicUsize, Ordering};
+
+/// Global cache for tracking PageRecorder instances.
+/// Used for invalidation when recorders are dropped or reset.
+static CACHE: OnceLock<DashMap<usize, ()>> = OnceLock::new();
+
+/// Counter for generating unique PageRecorder IDs
+static ID_COUNTER: AtomicUsize = AtomicUsize::new(1);
+
+/// Global page cache for PageRecorder ID management.
+pub struct PageCache;
+
+impl PageCache {
+ /// Get or initialize the shared cache
+ fn shared() -> &'static DashMap<usize, ()> {
+ CACHE.get_or_init(DashMap::new)
+ }
+
+ /// Generate a unique ID for a new PageRecorder
+ pub fn next_id() -> usize {
+ ID_COUNTER.fetch_add(1, Ordering::Relaxed)
+ }
+
+ /// Invalidate (remove) a cache entry.
+ /// Called when a canvas is cleared, resized, or reset.
+ pub fn invalidate(id: usize) {
+ let cache = Self::shared();
+ cache.remove(&id);
+ }

