+// =============================================================================
+// LRU CACHE
+// =============================================================================
+
+/**
+ * Simple LRU (Least Recently Used) cache implementation.
+ */
+class LRUCache<K, V> {
+ private cache = new Map<K, V>();
+ private readonly maxSize: number;
+
+ constructor(maxSize: number) {
+ this.maxSize = maxSize;
+ }
+
+ get(key: K): V | null {
+ const value = this.cache.get(key);
+ if (!value) return null;
+ // Move to end (most recently used)
+ this.cache.delete(key);
+ this.cache.set(key, value);
+ return value;
+ }
+
+ set(key: K, value: V): void {
+ // Evict oldest if at capacity
+ if (this.cache.size >= this.maxSize) {
+ const oldest = this.cache.keys().next().value;
+ if (oldest !== undefined) {
+ this.cache.delete(oldest);
+ }
+ }
+ this.cache.set(key, value);
+ }
+
+ clear(): void {
+ this.cache.clear();
+ }
+
+ size(): number {
+ return this.cache.size;
+ }
+}
+
+// =============================================================================
+// ETag CACHE
+// =============================================================================
+
+interface ETagEntry {
+ etag: string;
+ timestamp: number;
+}
+
+/**
+ * ETag-based cache with TTL (time-to-live) expiration.
+ */
+class ETagCache {
+ private cache = new Map<string, ETagEntry>();
+ private readonly defaultTtlMs: number;
+
+ constructor(defaultTtlMs: number = 30_000) {
+ this.defaultTtlMs = defaultTtlMs;
+ }
+
+ get(key: string): string | null {
+ const entry = this.cache.get(key);
+ if (!entry) return null;
+ // Check if expired
+ if (Date.now() - entry.timestamp > this.defaultTtlMs) {
+ this.cache.delete(key);
+ return null;
+ }
+ return entry.etag;
+ }
+
+ set(key: string, etag: string): void {
+ this.cache.set(key, {
+ etag,
+ timestamp: Date.now(),
+ });
+ }
